module freq_divbyfrac #(
    parameter MUL2_DIV_CLK = 7
) (
    input               rst_n,
    input               clk,
    output reg clk_div
);

    parameter PHASE_SHIFT = 3;


	reg[3:0] cnt_clk;           
	wire clk_edge;
	wire[3:0] div_cnt;          
	wire odd_clk;
	wire even_clk;
	wire clk_phase_shifted_odd;
	wire clk_phase_shifted_even;
	wire[3:0] cnt_next;         

	always @(posedge clk or negedge rst_n) begin
	    if(!rst_n)begin
	        cnt_clk <= 0;
	    end else begin
            cnt_clk <= cnt_next;
        end
	end

	assign div_cnt = cnt_clk % MUL2_DIV_CLK;
	assign clk_edge = |cnt_clk[MUL2_DIV_CLK - 1 -: 2];
	assign odd_clk = (div_cnt >= PHASE_SHIFT);
	assign even_clk = ~odd_clk;
	assign clk_phase_shifted_odd = ((even_clk && !clk_edge) || (odd_clk && clk_edge));
	assign clk_phase_shifted_even = (!even_clk && clk_edge);
	assign cnt_next = (clk_div)?(cnt_clk + 1):(0);

	always@(*)begin
        clk_div = clk_phase_shifted_odd | clk_phase_shifted_even;
    end
endmodule
